    28  /**
    29   * @file
    30   *   This file implements the radio platform callbacks into OpenThread and default/weak radio platform APIs.
    31   */
    32
    33  #include <openthread/instance.h>
    34
    35  #include "common/instance.hpp"
    36  #include "radio/radio.hpp"
    37
    38  using namespace ot;
    39
    40  //---------------------------------------------------------------------------------------------------------------------
    41  // otPlatRadio callbacks
    42
    43  extern "C" void otPlatRadioReceiveDone(otInstance *aInstance, otRadioFrame *aFrame, otError aError)
    44  {
    45      Instance *instance = static_cast<Instance *>(aInstance);
    46
    47      if (instance->IsInitialized())
    48      {
    49          instance->Get<Radio::Callbacks>().HandleReceiveDone(static_cast<Mac::RxFrame *>(aFrame), aError);
    50      }
    51  }
    52
    53  extern "C" void otPlatRadioTxStarted(otInstance *aInstance, otRadioFrame *aFrame)
    54  {
    55      Instance *instance = static_cast<Instance *>(aInstance);
    56
    57      if (instance->IsInitialized())
    58      {
    59          instance->Get<Radio::Callbacks>().HandleTransmitStarted(*static_cast<Mac::TxFrame *>(aFrame));
    60      }
    61  }
    62
    63  extern "C" void otPlatRadioTxDone(otInstance *aInstance, otRadioFrame *aFrame, otRadioFrame *aAckFrame, otError aError)
    64  {
    65      Instance *instance = static_cast<Instance *>(aInstance);
    66
    67      if (instance->IsInitialized())
    68      {
    69          instance->Get<Radio::Callbacks>().HandleTransmitDone(*static_cast<Mac::TxFrame *>(aFrame),
    70                                                               static_cast<Mac::RxFrame *>(aAckFrame), aError);
    71      }
    72  }
    73
    74  extern "C" void otPlatRadioEnergyScanDone(otInstance *aInstance, int8_t aEnergyScanMaxRssi)
    75  {
    76      Instance *instance = static_cast<Instance *>(aInstance);
    77
    78      if (instance->IsInitialized())
    79      {
    80          instance->Get<Radio::Callbacks>().HandleEnergyScanDone(aEnergyScanMaxRssi);
    81      }
    82  }
    83
    84  #if OPENTHREAD_CONFIG_MAC_HEADER_IE_SUPPORT
    85  extern "C" void otPlatRadioFrameUpdated(otInstance *aInstance, otRadioFrame *aFrame)
    86  {
    87      Instance *instance = static_cast<Instance *>(aInstance);
    88
    89      if (instance->IsInitialized())
    90      {
    91          instance->Get<Radio::Callbacks>().HandleFrameUpdated(*static_cast<Mac::TxFrame *>(aFrame));
    92      }
    93  }
    94  #endif
    95
    96  #if OPENTHREAD_CONFIG_DIAG_ENABLE
    97  extern "C" void otPlatDiagRadioReceiveDone(otInstance *aInstance, otRadioFrame *aFrame, otError aError)
    98  {
    99      Instance *instance = static_cast<Instance *>(aInstance);
   100
   101      instance->Get<Radio::Callbacks>().HandleDiagsReceiveDone(static_cast<Mac::RxFrame *>(aFrame), aError);
   102  }
   103
   104  extern "C" void otPlatDiagRadioTransmitDone(otInstance *aInstance, otRadioFrame *aFrame, otError aError)
   105  {
   106      Instance *instance = static_cast<Instance *>(aInstance);
   107
   108      instance->Get<Radio::Callbacks>().HandleDiagsTransmitDone(*static_cast<Mac::TxFrame *>(aFrame), aError);
   109  }
   110  #endif
   111
   112  //---------------------------------------------------------------------------------------------------------------------
   113  // Default/weak implementation of radio platform APIs
   114
   115  OT_TOOL_WEAK uint32_t otPlatRadioGetSupportedChannelMask(otInstance *aInstance)
   116  {
   117      OT_UNUSED_VARIABLE(aInstance);
   118
   119      return Radio::kSupportedChannels;
   120  }
   121
   122  OT_TOOL_WEAK uint32_t otPlatRadioGetPreferredChannelMask(otInstance *aInstance)
   123  {
   124      return otPlatRadioGetSupportedChannelMask(aInstance);
   125  }
   126
   127  OT_TOOL_WEAK const char *otPlatRadioGetVersionString(otInstance *aInstance)
   128  {
   129      OT_UNUSED_VARIABLE(aInstance);
   130      return otGetVersionString();
   131  }
